const AT = 'Attendant', FA = 'Flight attendant', TX = 'Taxi driver', PO = 'Police officer', REP = 'Representative', EM = 'Emma', LI = 'Lilly', DB = 'Debra', J03 = 'Jacob (2003)';
const day8 = 'OCTOBER 6TH 2003', day8b = 'OCTOBER 7TH 2003', day9 = 'OCTOBER 8TH 2003', ME = 'Chrisscape88', SAM = 'CaptainSammi06', work = { shirt:'#f0f0f0', top:'polo', vest:'#c8102e' };
const hide = () => { P.model.visible = false; };
const stand = (n, x, y, z, f) => { n.stop(); n.manual = true; n.o.position.set(x, y, z); n.o.rotation.y = f; n.p.set(x, 0, z); n.face = f; };
const gang = (pts, o = {}) => { const g = {}; [['zeke', ZK], ['matt', MT], ['jax', JX], ['milo', MI]].forEach(([k, nm], i) => { if(pts[i]) g[k] = mnpc(nm, LOOK[k], pts[i][0], pts[i][1], { face:pts[i][2] ?? 0, ...o }); }); return g; };
const trail = (g, sp = 5) => Object.values(g).forEach((n, i) => n.follow(P, 1.8 + i * .9, sp));
const halt = g => Object.values(g).forEach(n => n.stop());
const board = (pos, lines, ry = 0) => { const m = new THREE.Mesh(new THREE.PlaneGeometry(5.4, 2.1), new THREE.MeshBasicMaterial({ map:E.label(lines, { bg:'#0a0a12', fg:'#ffd23f', size:30, w:640, h:250, font:'Courier New' }) })); m.position.set(...pos); m.rotation.y = ry; G.scene.add(m); later(() => G.scene.remove(m)); return m; };
const dim = v => { G.R.domElement.style.filter = v ? `brightness(${v})` : ''; if(v) later(() => { G.R.domElement.style.filter = ''; }); };

